def compute(vars):
    goodwill = vars["v1"]
    total_consideration = vars["v2"]

    if total_consideration == 0:
        return None

    portion = goodwill / total_consideration
    return {
        "value": portion,
        "trace": {
            "goodwill": goodwill,
            "total_consideration": total_consideration,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "ratio"
            }
        }
    }
